const apiKey = '=&W8wZL=Q4E3z70N*X>>nWI!L/JhJ<QC6jy)VtioYBLx.kN_UfVT<{]e8Ia$N1+E';
const cvsBaseUrl = 'http://192.168.1.22:8080/wp-json/keoni/v1/cvs';
const jobBaseUrl = 'http://192.168.1.22:8080/wp-json/keoni/v1/job';
const chunkSize = 200;
const limit = 100;
let offset = 0;
const usable = [];

const jobPostId = $json?.body?.job_post_id;
if (!jobPostId) {
  throw new Error('Missing job_post_id in webhook payload');
}

const stripHtml = (value) => {
  if (!value) return '';
  return String(value).replace(/<[^>]*>/g, ' ');
};

const hasText = (cv) => {
  const sources = [
    cv.resume,
    cv.skills,
    cv.keywords,
    cv.text_content,
    cv.description,
  ];
  const combined = stripHtml(sources.filter(Boolean).join(' '))
    .replace(/\s+/g, ' ')
    .trim();
  return combined.length >= 30;
};

const headers = { 'X-API-Key': apiKey };
const job = await this.helpers.httpRequest({
  method: 'GET',
  url: `${jobBaseUrl}/${jobPostId}` ,
  headers,
});

while (true) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `${cvsBaseUrl}?offset=${offset}&limit=${limit}` ,
    headers,
  });

  const items = Array.isArray(response.items) ? response.items : [];
  const filtered = items.filter(hasText);
  if (filtered.length) {
    usable.push(...filtered);
  }

  if (items.length < limit) {
    break;
  }

  offset += limit;
}

if (!usable.length) {
  return [{ json: { ...job, cvs: [] } }];
}

const chunks = [];
for (let i = 0; i < usable.length; i += chunkSize) {
  const copy = JSON.parse(JSON.stringify(job));
  copy.cvs = usable.slice(i, i + chunkSize);
  chunks.push({ json: copy });
}

return chunks;

const apiKey = '=&W8wZL=Q4E3z70N*X>>nWI!L/JhJ<QC6jy)VtioYBLx.kN_UfVT<{]e8Ia$N1+E';
const cvEndpoint = 'http://192.168.1.22:8080/wp-json/keoni/v1/cv';
const syncChunkSize = 20;

function normalizeList(value) {
  if (Array.isArray(value)) {
    return value.map(v => String(v).trim()).filter(Boolean);
  }
  if (!value) {
    return [];
  }
  return String(value)
    .replace(/<[^>]*>/g, ' ')
    .split(/[,;\n]+/)
    .map(v => v.trim())
    .filter(Boolean);
}

function ensureMetadata(value) {
  if (!value) {
    return {};
  }
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        return parsed;
      }
      return {};
    } catch (error) {
      return {};
    }
  }
  if (typeof value === 'object' && !Array.isArray(value)) {
    return value;
  }
  return {};
}

function stripHtml(value) {
  if (!value) {
    return '';
  }
  return String(value).replace(/<[^>]*>/g, ' ');
}

function collectText(cv, meta) {
  const sources = [
    cv.text_content,
    cv.resume,
    cv.skills,
    cv.keywords,
    cv.description,
    meta.summary,
    meta.experience,
    meta.notes,
  ].filter(Boolean);

  if (!sources.length) {
    return '';
  }

  return sources
    .map(stripHtml)
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const syncCvToDatabase = async (cv) => {
  const email = cv.email || cv.candidate_email || '';
  const text = cv.text_content || '';

  if (!email || text.length < 30) {
    return;
  }

  const payload = {
    candidate_email: email,
    application_title: cv.title || cv.application_title || '',
    file_name: cv.file_name || cv.resume_file || '',
    file_path: cv.file_path || '',
    text_content: text,
    metadata: cv.metadata || {},
  };

  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: cvEndpoint,
      headers: {
        'X-API-Key': apiKey,
      },
      json: true,
      body: payload,
    });
  } catch (error) {
    const message = (error && error.message) ? error.message : 'unknown error';
    console.error(`CV sync failed for ${email}: ${message}`);
  }
};

const syncCvsInChunks = async (cvs) => {
  for (let i = 0; i < cvs.length; i += syncChunkSize) {
    const slice = cvs.slice(i, i + syncChunkSize);
    await Promise.all(slice.map(syncCvToDatabase));
  }
};

const jobRaw = $json;
const cvs = Array.isArray(jobRaw.cvs) ? jobRaw.cvs : [];
const normalizedCvs = cvs
  .map(cv => {
    const metadata = ensureMetadata(cv.metadata);
    const combined = collectText(cv, metadata);
    return {
      ...cv,
      metadata,
      text_content: combined,
    };
  })
  .filter(cv => (cv.text_content || '').length >= 30);

if (!normalizedCvs.length) {
  return [];
}

await syncCvsInChunks(normalizedCvs);

const job = {
  id: jobRaw.id,
  title: jobRaw.title,
  description: jobRaw.content || jobRaw.description || '',
  excerpt: jobRaw.excerpt || '',
  keywords: normalizeList(jobRaw.keywords),
  location: jobRaw.location || '',
  meta: jobRaw.meta || {},
};

const items = normalizedCvs.map(cv => ({ json: { job, cv } }));
return items;

const items = $input.all();
if (!items.length) {
  return [];
}
const job = items[0].json.job;
const cvs = items.map(item => item.json.cv);
return [{ json: { job, cvs } }];
